def detect_language(word):
    
    
    i_result_0_i = "en"
    
    if re.search(r'[\u0600-\u06FF]', word):
        i_result_0_i = "ar"

    elif re.search(r'[a-zA-Z]', word):
        i_result_0_i = "en"

    return i_result_0_i


